-- SECURITY DEFINER; API roles that may call it: service_role
CREATE OR REPLACE FUNCTION public.reconcile_stale_leaderboards()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c record;
  n integer := 0;
begin
  for c in
    select ch.id
    from public.challenges ch
    where ch.scoring is distinct from 'points'
      and exists (
        select 1 from public.submissions s
        where s.challenge_id = ch.id
          and s.views_synced_at is not null
          and s.views_synced_at > coalesce(ch.results_updated_at, '-infinity'::timestamptz)
      )
  loop
    perform public.rebuild_challenge_results(c.id);
    n := n + 1;
  end loop;
  return n;
end;
$function$;
